import { useCallback } from 'react';

import { useMultiMeterBarTooltipState } from './store/selectors.js';
import { useSetState } from './store/use-set-state.js';

//TODO ADES-4832 move to common meter-bar folder and reuse across meter and multimeter
export const useTooltip = () => {
  const setState = useSetState();
  const { pinned, visible } = useMultiMeterBarTooltipState();

  const hideTooltip = useCallback(() => {
    setState((prev) => {
      const newState = {
        ...prev,
        tooltip: { visible: false, pinned: false },
      };

      return newState;
    });
  }, [setState]);

  const showTooltip = useCallback(() => {
    setState((prev) => {
      const newState = {
        ...prev,
        tooltip: { ...prev.tooltip, visible: true },
      };

      return newState;
    });
  }, [setState]);

  const toggleTooltipPinnedState = useCallback(() => {
    setState((prev) => {
      const newState = {
        ...prev,
        tooltip: { ...prev.tooltip, pinned: !prev.tooltip.pinned },
      };

      return newState;
    });
  }, [setState]);

  const updateTooltipContent = (segmentId: string) => {
    setState((prev) => {
      const newSegment = prev.visibleSegments.get(segmentId);
      if (newSegment === undefined || prev.tooltip.pinned) {
        return prev;
      }

      const newState = {
        ...prev,
        tooltip: {
          ...prev.tooltip,
          content: {
            name: newSegment.name,
            id: newSegment.id,
            color: { Default: newSegment.color },
            values: [newSegment.value.toString()],
          },
        },
      };

      return newState;
    });
  };

  const hideTooltipHandler = () => {
    if (!pinned) {
      hideTooltip();
    }
  };

  const showTooltipHandler = () => {
    if (!pinned) {
      showTooltip();
    }
  };

  const toggleTooltipPinnedStateHandler = () => {
    if (visible) {
      toggleTooltipPinnedState();
    }
  };

  const updateTooltipContentHandler = (segmentId: string) => {
    updateTooltipContent(segmentId);
  };

  return {
    hideTooltip,
    hideTooltipHandler,
    showTooltip,
    showTooltipHandler,
    toggleTooltipPinnedState,
    toggleTooltipPinnedStateHandler,
    updateTooltipContentHandler,
  };
};
